body::after {
  content: '';
  position: fixed;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(147, 51, 234, 0.15) 0%, rgba(0,0,0,0) 70%);
  z-index: -1;
  pointer-events: none;
  animation: consciousGrowth 20s infinite alternate cubic-bezier(0.4, 0, 0.2, 1);
}

@keyframes consciousGrowth {
  0% {
    transform: scale(0.8);
    opacity: 0.5;
  }
  100% {
    transform: scale(1.2);
    opacity: 1;
  }
}

body {
  background: radial-gradient(circle at center, #2a0005 0%, #000000 100%) !important;
  animation: passionPulse 4s ease-in-out infinite alternate !important;
}
@keyframes passionPulse {
  0% { box-shadow: inset 0 0 50px #ff2a00; }
